<div class="page-heading"><div><p class="eyebrow">KALKULATOR</p><h1>Estimasi Biaya LCL</h1><p>Pilih POD, masukkan CBM, lalu sistem menghitung seluruh tarif dari daftar FOB.</p></div><a class="button button-secondary" href="{{ route('calculators.index') }}">← Kembali</a></div>
<section class="panel form-panel calculator-panel calc-detail-card"><form class="data-form calculator-form" id="lcl-form"><div class="calc-detail-head"><div class="calc-icon-badge amber"><x-icon name="briefcase"/></div><h2>Rute dan Tarif LCL</h2></div><div class="form-grid"><div class="field"><label>POL</label><input value="Jakarta" readonly></div><div class="field"><label for="lcl_rate_id">POD / FOB Port</label><select id="lcl_rate_id" required><option value="">Pilih POD dari FOB Port</option></select></div><div class="field"><label>Transit</label><input id="transit" readonly placeholder="Terisi dari Excel"></div><div class="field"><label>Lead Time</label><input id="lead_time" readonly placeholder="Terisi dari Excel"></div></div><div class="form-grid" style="margin-top:16px"><div class="field"><label>O/F (USD / W/M)</label><input id="ocean_freight_rate" value="0" readonly></div><div class="field"><label>GRI (USD / W/M)</label><input id="gri_rate" value="0" readonly></div><div class="field"><label>CFS (USD / W/M)</label><input id="cfs_rate" value="0" readonly></div><div class="field"><label>Minimum CFS (W/M)</label><input id="cfs_min_wm" value="2" readonly></div><div class="field"><label>Others (USD / set)</label><input id="others_per_set" value="0" readonly></div><div class="field"><label>Mekanik (IDR / W/M)</label><input id="mechanic_rate" value="0" readonly></div><div class="field"><label>Minimum Mekanik (W/M)</label><input id="mechanic_min_wm" value="2" readonly></div><div class="field"><label>Admin (IDR / set)</label><input id="administration" value="0" readonly></div></div><div class="lcl-cbm-input"><div><span class="lcl-upload-kicker">INPUT UTAMA</span><h3>Volume pengiriman</h3><p>Masukkan total CBM. Tidak perlu input Qty, ukuran, atau berat barang.</p></div><div class="field"><label for="cbm">CBM</label><input id="cbm" type="number" min="0.01" step="0.001" placeholder="Contoh: 2.5" required><small>m³</small></div></div><p class="form-help">O/F dan GRI = tarif × CBM. CFS dan Mekanik memakai <strong>MIN</strong> bila CBM di bawah nilai minimum, misalnya MIN 2 berarti tarif × 2. Others dan Admin tidak dikalikan CBM.</p><div class="form-actions"><button class="button button-primary">Hitung estimasi LCL</button></div></form><div class="cost-summary-body calc-result-card" id="lcl-result" hidden><div class="stats-grid"><div class="stat-card"><p>CBM</p><strong id="r-cbm">—</strong></div><div class="stat-card"><p>Basis W/M</p><strong id="r-basis">—</strong></div><div class="stat-card"><p>Total USD</p><strong id="r-usd">—</strong></div><div class="stat-card"><p>Total IDR</p><strong id="r-idr">—</strong></div></div><div class="summary-box" style="margin-top:16px"><div class="summary-row"><span>O/F</span><strong id="r-of">—</strong></div><div class="summary-row"><span>GRI</span><strong id="r-gri">—</strong></div><div class="summary-row"><span>CFS</span><strong id="r-cfs">—</strong></div><div class="summary-row"><span>Others</span><strong id="r-others">—</strong></div><div class="summary-row"><span>Mekanik</span><strong id="r-mechanic">—</strong></div><div class="summary-row"><span>Admin</span><strong id="r-administration">—</strong></div></div></div></section>
<script>(()=>{const f=document.getElementById('lcl-form'),select=document.getElementById('lcl_rate_id'),fields=['ocean_freight_rate','gri_rate','cfs_rate','cfs_min_wm','others_per_set','mechanic_rate','mechanic_min_wm','administration'];let rates=[];const fmtNum=v=>{if(v===null||v===undefined||v==='')return'0';let n=Number(v);return isNaN(n)?v:String(n)};fetch('{{ route('lcl-rates.options') }}').then(r=>r.json()).then(data=>{rates=data;data.forEach(rate=>{let o=document.createElement('option');o.value=rate.id;o.textContent=[rate.fob_port,rate.country,rate.customer,rate.subject].filter(Boolean).join(' — ');select.append(o)})});select.onchange=()=>{let rate=rates.find(x=>x.id===Number(select.value));if(!rate)return;document.getElementById('transit').value=rate.subject||'—';document.getElementById('lead_time').value=fmtNum(rate.lead_time_days||0)+' hari';fields.forEach(k=>document.getElementById(k).value=fmtNum(rate[k]??0))};f.onsubmit=e=>{e.preventDefault();if(!select.value)return select.focus();let cbm=Number(document.getElementById('cbm').value),p=new URLSearchParams({lcl_rate_id:select.value,cbm});fields.forEach(k=>p.set(k,document.getElementById(k).value));fetch('{{ route('calculators.api.lcl') }}?'+p).then(r=>r.json()).then(d=>{if(!d.total_cbm)return;let u=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}),i=new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR'}),cfsNote=cbm<Number(document.getElementById('cfs_min_wm').value)?'MIN '+fmtNum(d.cfs_basis):fmtNum(d.cfs_basis)+'× tarif',mechanicNote=cbm<Number(document.getElementById('mechanic_min_wm').value)?'MIN '+fmtNum(d.mechanic_basis):fmtNum(d.mechanic_basis)+'× tarif';document.getElementById('lcl-result').hidden=false;[['r-cbm',fmtNum(d.total_cbm)+' m³'],['r-basis',fmtNum(d.chargeable_basis)+' W/M'],['r-usd',u.format(d.total_usd)],['r-idr',i.format(d.total_idr)],['r-of',u.format(d.usd.ocean_freight)],['r-gri',u.format(d.usd.gri)],['r-cfs',u.format(d.usd.cfs)+' ('+cfsNote+')'],['r-others',u.format(d.usd.others)],['r-mechanic',i.format(d.idr.mechanic)+' ('+mechanicNote+')'],['r-administration',i.format(d.idr.administration)]].forEach(([id,v])=>document.getElementById(id).textContent=v)})}})();</script>
